INSERT INTO "Requirement" (id, "requirementId", "familyId", title, "basicRequirement", discussion, "furtherDiscussion", "exampleOne", "exampleTwo", "potentialAssessmentConsiderations", "keyReferences", "cmmcLevel", "sortOrder", "createdAt", "updatedAt")
VALUES ('ij03zph6pmogyqx32wrveoyb', '03.09.01', 'd3figq9ry1v1z0cqo5cdgno5', 'Screen Individuals', $body$Screen individuals prior to authorizing access to organizational systems containing CUI.$body$, $body$Personnel security screening (vetting) activities involve the evaluation/assessment of 
individual’s conduct, integrity, judgment, loyalty, reliability, and stability (i.e., the 
trustworthiness of the individual) prior to authorizing access to organizational systems 
containing CUI. The screening activities reflect applicable federal laws, Executive Orders, 
directives, policies, regulations, and specific criteria established for the level of access 
required for assigned positions.$body$, $body$Ensure all employees who need access to CUI undergo organization-defined screening before 
being granted access. Base the types of screening on the requirements for a given position 
and role. 


The effective screening of personnel provided by this requirement, PS.L2-3.9.1, improves 
upon the effectiveness of authentication performed in IA.L2-3.5.2.$body$, $body$You are in charge of security at your organization. You complete standard criminal 
background and credit checks of all individuals you hire before they can access CUI [a]. Your 
screening program follows appropriate laws, policies, regulations, and criteria for the level 
of access required for each position.$body$, NULL, $body$• Are appropriate background checks completed prior granting access to organizational 
systems containing CUI [a]?$body$, $body$• NIST SP 800-171 Rev. 2 3.9.1$body$, 'LEVEL_2', 1, NOW(), NOW())
