INSERT INTO "Requirement" (id, "requirementId", "familyId", title, "basicRequirement", discussion, "furtherDiscussion", "exampleOne", "exampleTwo", "potentialAssessmentConsiderations", "keyReferences", "cmmcLevel", "sortOrder", "createdAt", "updatedAt")
VALUES ('fy7glq1csxpk66nocculj02x', '03.10.02', 'swrx7nugncm7epap4zgijaut', 'Monitor Facility', $body$Protect and monitor the physical facility and support infrastructure for organizational systems.$body$, $body$Monitoring of physical access includes publicly accessible areas within organizational 
facilities. This can be accomplished, for example, by the employment of guards; the use of 
sensor devices; or the use of video surveillance equipment such as cameras. Examples of 
support infrastructure include system distribution, transmission, and power lines. Security 
controls applied to the support infrastructure prevent accidental damage, disruption, and 
physical tampering. Such controls may also be necessary to prevent eavesdropping or 
modification of unencrypted transmissions. Physical access controls to support 
infrastructure include locked wiring closets; disconnected or locked spare jacks; protection 
of cabling by conduit or cable trays; and wiretapping sensors.$body$, $body$The infrastructure inside of a facility, such as power and network cables, is protected so that 
visitors and unauthorized employees cannot access it. The protection is also monitored by 
security guards, video cameras, sensors, or alarms.$body$, $body$You are responsible for protecting your IT facilities. You install video cameras at each 
entrance and exit, connect them to a video recorder, and show the camera feeds on a display 
at the reception desk [c,d]. You also make sure there are secure locks on all entrances, exits, 
and windows to the facilities [a,b].$body$, NULL, $body$• Is physical access monitored to detect and respond to physical security incidents [c, d]?$body$, $body$• NIST SP 800-171 Rev 2 3.10.2$body$, 'LEVEL_2', 2, NOW(), NOW())
ON CONFLICT ("requirementId") DO UPDATE SET title = EXCLUDED.title, "basicRequirement" = EXCLUDED."basicRequirement", discussion = EXCLUDED.discussion, "furtherDiscussion" = EXCLUDED."furtherDiscussion", "exampleOne" = EXCLUDED."exampleOne", "exampleTwo" = EXCLUDED."exampleTwo", "potentialAssessmentConsiderations" = EXCLUDED."potentialAssessmentConsiderations", "keyReferences" = EXCLUDED."keyReferences", "sortOrder" = EXCLUDED."sortOrder", "updatedAt" = NOW();

INSERT INTO "Requirement" (id, "requirementId", "familyId", title, "basicRequirement", discussion, "furtherDiscussion", "exampleOne", "exampleTwo", "potentialAssessmentConsiderations", "keyReferences", "cmmcLevel", "sortOrder", "createdAt", "updatedAt")
VALUES ('tdgg0a3m0moo592yk4fzsymv', '03.10.03', 'swrx7nugncm7epap4zgijaut', 'Escort Visitors', $body$Escort visitors and monitor visitor activity.$body$, $body$Individuals with permanent physical access authorization credentials are not considered 
visitors. Audit logs can be used to monitor visitor activity.$body$, $body$Do not allow visitors, even those people you know well, to walk around your facility without 
an escort. Make sure that all non-employees wear special visitor badges and/or are escorted 
by an employee at all times while on the property.$body$, $body$Coming back from a meeting, you see the friend of a coworker walking down the hallway 
near your office. You know this person well and trust them, but are not sure why they are in 
the building. You stop to talk, and the person explains that they are meeting a coworker for 
lunch, but cannot remember where the lunchroom is. You walk the person back to the 
reception area to get a visitor badge and wait until someone can escort them to the lunch 
room [a]. You report this incident and the company decides to install a badge reader at the 
main door so visitors cannot enter without an escort [a].$body$, NULL, $body$• Are personnel required to accompany visitors to areas in a facility with physical access 
to organizational systems [a]? 
• Are visitors clearly distinguishable from regular personnel [b]? 
• Is visitor activity monitored (e.g., use of cameras or guards, reviews of secure areas upon 
visitor departure, review of visitor audit logs) [b]?$body$, $body$• NIST SP 800-171 Rev. 2 3.10.3 
• FAR Clause 52.204-21 Partial b.1.ix$body$, 'LEVEL_2', 3, NOW(), NOW())
ON CONFLICT ("requirementId") DO UPDATE SET title = EXCLUDED.title, "basicRequirement" = EXCLUDED."basicRequirement", discussion = EXCLUDED.discussion, "furtherDiscussion" = EXCLUDED."furtherDiscussion", "exampleOne" = EXCLUDED."exampleOne", "exampleTwo" = EXCLUDED."exampleTwo", "potentialAssessmentConsiderations" = EXCLUDED."potentialAssessmentConsiderations", "keyReferences" = EXCLUDED."keyReferences", "sortOrder" = EXCLUDED."sortOrder", "updatedAt" = NOW();

INSERT INTO "Requirement" (id, "requirementId", "familyId", title, "basicRequirement", discussion, "furtherDiscussion", "exampleOne", "exampleTwo", "potentialAssessmentConsiderations", "keyReferences", "cmmcLevel", "sortOrder", "createdAt", "updatedAt")
VALUES ('bhki6bja8j3wkpx7qv9lb9tm', '03.10.04', 'swrx7nugncm7epap4zgijaut', 'Physical Access Logs', $body$Maintain audit logs of physical access.$body$, $body$Organizations have flexibility in the types of audit logs employed. Audit logs can be 
procedural (e.g., written log of individuals accessing the facility), automated (e.g., capturing 
ID provided by a PIV card), or some combination thereof. Physical access points can include 
facility access points, interior access points to systems or system components requiring 
supplemental access controls, or both. System components (e.g., workstations, notebook 
computers) may be in areas designated as publicly accessible with organizations 
safeguarding access to such devices.$body$, $body$Make sure you have a record of who accesses your facility (e.g., office, plant, factory). You can 
do this in writing by having employees and visitors sign in and sign out or by electronic 


means such as badge readers. Whatever means you use, you need to retain the access records 
for the time period that your company has defined.$body$, $body$You and your coworkers like to have friends and family join you for lunch at the office on 
Fridays. Your small company has just signed a contract with the DoD, however, and you now 
need to document who enters and leaves your facility. You work with the reception staff to 
ensure that all non-employees sign in at the reception area and sign out when they leave [a]. 
You retain those paper sign-in sheets in a locked filing cabinet for one year. Employees 
receive badges or key cards that enable tracking and logging access to company facilities.$body$, NULL, $body$• Are logs of physical access to sensitive areas (both authorized access and visitor access) 
maintained per retention requirements [a]? 
• Are visitor access records retained for as long as required [a]?$body$, $body$• NIST SP 800-171 Rev. 2 3.10.4 
• FAR Clause 52.204-21 Partial b.1.ix$body$, 'LEVEL_2', 4, NOW(), NOW())
ON CONFLICT ("requirementId") DO UPDATE SET title = EXCLUDED.title, "basicRequirement" = EXCLUDED."basicRequirement", discussion = EXCLUDED.discussion, "furtherDiscussion" = EXCLUDED."furtherDiscussion", "exampleOne" = EXCLUDED."exampleOne", "exampleTwo" = EXCLUDED."exampleTwo", "potentialAssessmentConsiderations" = EXCLUDED."potentialAssessmentConsiderations", "keyReferences" = EXCLUDED."keyReferences", "sortOrder" = EXCLUDED."sortOrder", "updatedAt" = NOW();

INSERT INTO "Requirement" (id, "requirementId", "familyId", title, "basicRequirement", discussion, "furtherDiscussion", "exampleOne", "exampleTwo", "potentialAssessmentConsiderations", "keyReferences", "cmmcLevel", "sortOrder", "createdAt", "updatedAt")
VALUES ('pc0qz5c43oayskk73fomsli8', '03.10.05', 'swrx7nugncm7epap4zgijaut', 'Manage Physical Access', $body$Control and manage physical access devices.$body$, $body$Physical access devices include keys, locks, combinations, and card readers.$body$, $body$Identifying and controlling physical access devices (e.g., locks, badges, key cards) is just as 
important as monitoring and limiting who is able to physically access certain equipment. 
Physical access devices are only strong protection if you know who has them and what access 
they allow. Physical access devices can be managed using manual or automatic processes 


such a list of who is assigned what key, or updating the badge access system as personnel 
change roles.$body$, $body$You are a facility manager. A team member retired today and returns their company keys to 
you. The project on which they were working requires access to areas that contain 
equipment with CUI. You receive the keys, check your electronic records against the serial 
numbers on the keys to ensure all have been returned, and mark each key returned [c].$body$, NULL, $body$• Are lists or inventories of physical access devices maintained (e.g., keys, facility badges, 
key cards) [a]? 
• Is access to physical access devices limited (e.g., granted to, and accessible only by, 
authorized individuals) [b]? 
• Are physical access devices managed (e.g., revoking key card access when necessary, 
changing locks as needed, maintaining access control devices and systems) [c]?$body$, $body$• NIST SP 800-171 Rev. 2 3.10.5 
• FAR Clause 52.204-21 Partial b.1.ix$body$, 'LEVEL_2', 5, NOW(), NOW())
