INSERT INTO "Requirement" (id, "requirementId", "familyId", title, "basicRequirement", discussion, "furtherDiscussion", "exampleOne", "exampleTwo", "potentialAssessmentConsiderations", "keyReferences", "cmmcLevel", "sortOrder", "createdAt", "updatedAt")
VALUES ('auqrtj4ro1otzno7vfu7orjq', '03.14.05', 'q9u578w0a1v75yjm4qm9ni8n', 'System & File Scanning', $body$Perform periodic scans of organizational systems and real-time scans of files from external sources as files are downloaded, opened, or executed.$body$, $body$Periodic scans of organizational systems and real-time scans of files from external sources 
can detect malicious code. Malicious code can be encoded in various formats (e.g., 


UUENCODE, Unicode), contained within compressed or hidden files, or hidden in files using 
techniques such as steganography. Malicious code can be inserted into systems in a variety 
of ways including web accesses, electronic mail, electronic mail attachments, and portable 
storage devices. Malicious code insertions occur through the exploitation of system 
vulnerabilities.$body$, $body$Use anti-malware software to scan for and identify viruses in your computer systems and 
determine how often scans are conducted. Real-time scans look at the system whenever new 
files are downloaded, opened, and saved. Periodic scans check previously saved files against 
updated malware information.$body$, $body$You work with your company’s email provider to enable enhanced protections that will scan 
all attachments to identify and quarantine those that may be harmful prior to a user opening 
them [c]. In addition, you configure antivirus software on each computer to scan for 
malicious code every day [a,b]. The software also scans files that are downloaded or copied 
from removable media such as USB drives. It quarantines any suspicious files and notifies 
the security team [c].$body$, NULL, $body$• Are files from media (e.g., USB drives, CD-ROM) included in the definition of external 
sources and are they being scanned [c]?$body$, $body$• NIST SP 800-171 Rev. 2 3.14.5 
• FAR Clause 52.204-21 b.1.xv$body$, 'LEVEL_2', 5, NOW(), NOW())
